class FfiConverterTypeCancellationSignal : FfiConverter<CancellationSignal, ulong>
{
    public static FfiConverterTypeCancellationSignal INSTANCE = new FfiConverterTypeCancellationSignal();

    public override ulong Lower(CancellationSignal value)
    {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override CancellationSignal Lift(ulong value)
    {
        return new CancellationSignal(value);
    }

    public override CancellationSignal Read(BigEndianStream stream)
    {
        return Lift(stream.ReadULong());
    }

    public override int AllocationSize(CancellationSignal value)
    {
        return 8;
    }

    public override void Write(CancellationSignal value, BigEndianStream stream)
    {
        stream.WriteULong(Lower(value));
    }
}

