/// <summary>
/// Structured fields extracted from a tracing event, organized by type.
///
/// Fields are separated by their native types to preserve type information
/// across the FFI boundary, enabling proper structured logging in C#. This
/// allows C# loggers to format numeric values appropriately rather than
/// treating everything as strings.
///
/// Values that cannot be represented in the native type maps (such as `i128`
/// and `u128`) are converted to strings and stored in the
/// [`strings`](Self::strings) map.
/// </summary>
/// <param name="Strings">
/// String-typed fields, including debug-formatted values and `i128`/`u128`.
/// </param>
/// <param name="I64s">
/// Signed 64-bit integer fields (maps to C# `long`).
/// </param>
/// <param name="U64s">
/// Unsigned 64-bit integer fields (maps to C# `ulong`).
/// </param>
/// <param name="F64s">
/// 64-bit floating point fields (maps to C# `double`).
/// </param>
/// <param name="Bools">
/// Boolean fields (maps to C# `bool`).
/// </param>
internal record LogFields(
    /// <summary>
    /// String-typed fields, including debug-formatted values and `i128`/`u128`.
    /// </summary>
    Dictionary<string, string> Strings,
    /// <summary>
    /// Signed 64-bit integer fields (maps to C# `long`).
    /// </summary>
    Dictionary<string, long> I64s,
    /// <summary>
    /// Unsigned 64-bit integer fields (maps to C# `ulong`).
    /// </summary>
    Dictionary<string, ulong> U64s,
    /// <summary>
    /// 64-bit floating point fields (maps to C# `double`).
    /// </summary>
    Dictionary<string, double> F64s,
    /// <summary>
    /// Boolean fields (maps to C# `bool`).
    /// </summary>
    Dictionary<string, bool> Bools
) { }

class FfiConverterTypeLogFields : FfiConverterRustBuffer<LogFields>
{
    public static FfiConverterTypeLogFields INSTANCE = new FfiConverterTypeLogFields();

    public override LogFields Read(BigEndianStream stream)
    {
        return new LogFields(
            Strings: FfiConverterDictionaryStringString.INSTANCE.Read(stream),
            I64s: FfiConverterDictionaryStringInt64.INSTANCE.Read(stream),
            U64s: FfiConverterDictionaryStringUInt64.INSTANCE.Read(stream),
            F64s: FfiConverterDictionaryStringDouble.INSTANCE.Read(stream),
