/// <summary>
/// Declares one keyed-state collection to register before subscribe.
/// </summary>
/// <param name="Name">
/// The collection name. Must be non-empty and unique within the client's
/// definition set.
/// </param>
/// <param name="Kind">
/// The collection kind.
/// </param>
/// <param name="Payload">
/// The item payload.
/// </param>
/// <param name="Ttl">
/// Optional per-write TTL. Must be a whole number of seconds of at least 1
/// (fractional and sub-second values are rejected) and must exceed the
/// recovery delay (the latter checked at consumer build).
/// </param>
/// <param name="ReadUncommitted">
/// Optional opt-out of transactional staging (read-uncommitted, at-least
/// once). Defaults to transactional.
/// </param>
/// <param name="KeysetLimit">
/// Optional map-only keyset bound (`0..=4096`; default 128 core-side; `0`
/// disables ordered-scan tracking). Invalid on value or deque collections.
/// </param>
/// <param name="Capacity">
/// Optional deque-only capacity bound (positive). Runtime-only — never
/// persisted, not part of identity; enforced lazily on push. Invalid on
/// value or map collections.
/// </param>
/// <param name="Published">
/// Whether owners advertise this collection for cross-group reads.
/// </param>
/// <param name="ReadCacheTtl">
/// Per-reader cache TTL override.
/// </param>
/// <param name="ReadCacheDisabled">
/// Whether readers bypass their cache for this collection.
/// </param>
internal record StateCollectionConfig(
    /// <summary>
    /// The collection name. Must be non-empty and unique within the client's
    /// definition set.
    /// </summary>
    string Name,
    /// <summary>
    /// The collection kind.
    /// </summary>
    StateKind Kind,
    /// <summary>
    /// The item payload.
    /// </summary>
    StatePayload Payload,
    /// <summary>
    /// Optional per-write TTL. Must be a whole number of seconds of at least 1
    /// (fractional and sub-second values are rejected) and must exceed the
    /// recovery delay (the latter checked at consumer build).
    /// </summary>
    TimeSpan? Ttl = null,
    /// <summary>
    /// Optional opt-out of transactional staging (read-uncommitted, at-least
    /// once). Defaults to transactional.
    /// </summary>
    bool? ReadUncommitted = null,
    /// <summary>
    /// Optional map-only keyset bound (`0..=4096`; default 128 core-side; `0`
    /// disables ordered-scan tracking). Invalid on value or deque collections.
    /// </summary>
    uint? KeysetLimit = null,
    /// <summary>
    /// Optional deque-only capacity bound (positive). Runtime-only — never
    /// persisted, not part of identity; enforced lazily on push. Invalid on
    /// value or map collections.
    /// </summary>
    uint? Capacity = null,
    /// <summary>
    /// Whether owners advertise this collection for cross-group reads.
    /// </summary>
    bool Published = false,
    /// <summary>
    /// Per-reader cache TTL override.
    /// </summary>
    TimeSpan? ReadCacheTtl = null,
    /// <summary>
    /// Whether readers bypass their cache for this collection.
    /// </summary>
    bool ReadCacheDisabled = false
) { }

class FfiConverterTypeStateCollectionConfig : FfiConverterRustBuffer<StateCollectionConfig>
{
    public static FfiConverterTypeStateCollectionConfig INSTANCE = new FfiConverterTypeStateCollectionConfig();

