/// <summary>
/// Determines how the client handles message processing failures.
///
/// Each mode offers different trade-offs between reliability and throughput:
///
/// - [`Pipeline`][Self::Pipeline]: Maximum reliability with automatic deferral
/// - [`LowLatency`][Self::LowLatency]: Bounded retries with dead-letter queue
/// - [`BestEffort`][Self::BestEffort]: Fire-and-forget for non-critical
/// workloads
/// </summary>
internal enum ClientMode : int
{
    /// <summary>
    /// Retries failed messages indefinitely using deferral and monopolization
    /// detection.
    ///
    /// This is the default mode for production workloads where no message loss
    /// is acceptable. Failed messages are deferred and retried with exponential
    /// backoff. Hot keys that monopolize processing are automatically
    /// throttled.
    /// </summary>
    Pipeline,

    /// <summary>
    /// Retries a bounded number of times, then sends to a dead-letter topic.
    ///
    /// Use when you need predictable latency and can reprocess failures later.
    /// Requires [`ClientOptions::failure_topic`] to be set.
    /// </summary>
    LowLatency,

    /// <summary>
    /// Logs failures and moves on without retrying.
    ///
    /// Use for development, testing, or workloads where occasional message
    /// loss is acceptable.
    /// </summary>
    BestEffort,
}

class FfiConverterTypeClientMode : FfiConverterRustBuffer<ClientMode>
{
    public static FfiConverterTypeClientMode INSTANCE = new FfiConverterTypeClientMode();

    public override ClientMode Read(BigEndianStream stream)
    {
        var value = stream.ReadInt();
        switch (value)
        {
            case 1:
                return ClientMode.Pipeline;
            case 2:
                return ClientMode.LowLatency;
            case 3:
                return ClientMode.BestEffort;
            default:
                throw new InternalException(
                    String.Format("invalid enum value '{0}' in FfiConverterTypeClientMode.Read()", value)
                );
        }
    }

    public override int AllocationSize(ClientMode value)
    {
        return 4;
    }

    public override void Write(ClientMode value, BigEndianStream stream)
    {
        switch (value)
        {
            case ClientMode.Pipeline:
                stream.WriteInt(1);
                break;
            case ClientMode.LowLatency:
                stream.WriteInt(2);
                break;
            case ClientMode.BestEffort:
                stream.WriteInt(3);
                break;
            default:
                throw new InternalException(
                    String.Format("invalid enum value '{0}' in FfiConverterTypeClientMode.Write()", value)
                );
        }
    }
}

/// <summary>
/// Represents the current lifecycle state of a consumer.
///
/// The normal lifecycle progresses linearly:
/// [`Unconfigured`][Self::Unconfigured] -> [`Configured`][Self::Configured] ->
/// [`Running`][Self::Running].
///
/// If the consumer configuration fails during build (e.g. invalid mode,
/// missing required fields), the state transitions to
/// [`ConfigurationFailed`][Self::ConfigurationFailed] instead of
/// [`Configured`][Self::Configured].
/// </summary>
internal record ConsumerState
{
    /// <summary>
    /// Initial state before configuration is applied.
    /// </summary>
    public record Unconfigured : ConsumerState { }

    /// <summary>
    /// Configuration applied but consumption not yet started.
    /// </summary>
    public record Configured : ConsumerState { }

    /// <summary>
    /// Actively polling and processing messages.
    /// </summary>
    public record Running : ConsumerState { }

    /// <summary>
    /// Configuration failed during build.
    /// </summary>
    public record ConfigurationFailed(string Message) : ConsumerState { }
}

class FfiConverterTypeConsumerState : FfiConverterRustBuffer<ConsumerState>
{
    public static FfiConverterRustBuffer<ConsumerState> INSTANCE = new FfiConverterTypeConsumerState();

    public override ConsumerState Read(BigEndianStream stream)
    {
        var value = stream.ReadInt();
        switch (value)
        {
            case 1:
                return new ConsumerState.Unconfigured();
            case 2:
                return new ConsumerState.Configured();
            case 3:
                return new ConsumerState.Running();
            case 4:
                return new ConsumerState.ConfigurationFailed(FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(
                    String.Format("invalid enum value '{0}' in FfiConverterTypeConsumerState.Read()", value)
                );
        }
    }

    public override int AllocationSize(ConsumerState value)
    {
        switch (value)
        {
            case ConsumerState.Unconfigured variant_value:
                return 4;
            case ConsumerState.Configured variant_value:
                return 4;
            case ConsumerState.Running variant_value:
                return 4;
            case ConsumerState.ConfigurationFailed variant_value:
                return 4 + FfiConverterString.INSTANCE.AllocationSize(variant_value.Message);
            default:
                throw new InternalException(
                    String.Format("invalid enum value '{0}' in FfiConverterTypeConsumerState.AllocationSize()", value)
                );
        }
    }

    public override void Write(ConsumerState value, BigEndianStream stream)
    {
        switch (value)
        {
            case ConsumerState.Unconfigured variant_value:
                stream.WriteInt(1);
                break;
            case ConsumerState.Configured variant_value:
                stream.WriteInt(2);
                break;
            case ConsumerState.Running variant_value:
                stream.WriteInt(3);
                break;
            case ConsumerState.ConfigurationFailed variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.Message, stream);
                break;
            default:
                throw new InternalException(
                    String.Format("invalid enum value '{0}' in FfiConverterTypeConsumerState.Write()", value)
                );
        }
    }
}

/// <summary>
/// Primary error type for FFI boundary operations.
///
/// `UniFFI` generates a corresponding `FfiException` type in C#. The
/// `flat_error` attribute serializes all variants to strings via their
/// `Display` implementation, preserving error messages across the language
/// boundary.
///
/// All variants support automatic conversion via [`From`] implementations,
/// allowing use of the `?` operator in FFI functions.
/// </summary>
internal class FfiException : UniffiException
{
    FfiException(string message)
        : base(message) { }

    // Each variant is a nested class
    // Flat enums carries a string error message, so no special implementation is necessary.

    /// <summary>
    /// The operation was cancelled before completion.
    /// </summary>
    public class Cancelled : FfiException
    {
        public Cancelled(string message)
            : base(message) { }
    }

    /// <summary>
    /// A topic name contains an invalid null byte.
    ///
    /// Kafka topic names must be valid C strings for interop with librdkafka.
    /// </summary>
    public class TopicContainsNul : FfiException
    {
        public TopicContainsNul(string message)
            : base(message) { }
    }

    /// <summary>
    /// An unexpected error occurred in a `UniFFI` callback.
    ///
    /// This typically indicates a bug in the generated bindings or a panic
    /// in callback code.
    /// </summary>
    public class UnexpectedCallback : FfiException
    {
        public UnexpectedCallback(string message)
            : base(message) { }
    }

    /// <summary>
    /// A Kafka admin operation failed.
    ///
    /// Wraps errors from topic creation, deletion, and metadata operations.
    /// </summary>
    public class Admin : FfiException
    {
        public Admin(string message)
            : base(message) { }
    }

    /// <summary>
    /// Configuration validation failed.
    ///
    /// One or more configuration values did not pass validation rules.
    /// </summary>
    public class Validation : FfiException
    {
        public Validation(string message)
            : base(message) { }
    }

    /// <summary>
    /// A telemetry emitter configuration builder could not be finalized.
    ///
    /// Occurs when an environment variable contains an invalid value for its
    /// corresponding configuration field (e.g. `PROSODY_TELEMETRY_ENABLED`
    /// is not a valid boolean).
    /// </summary>
    public class TelemetryConfig : FfiException
    {
        public TelemetryConfig(string message)
            : base(message) { }
    }

    /// <summary>
    /// Flushing or shutting down the telemetry pipeline failed.
    ///
    /// Wraps errors from exporting buffered OpenTelemetry spans/metrics or from
    /// tearing the export pipeline down at process exit.
    /// </summary>
    public class Tracing : FfiException
    {
        public Tracing(string message)
            : base(message) { }
    }

    /// <summary>
    /// A Kafka message loader configuration could not be finalized.
    ///
    /// Occurs when the Kafka loader tuning derived from
    /// `loader_cache_size`, `loader_seek_timeout`, or
    /// `loader_discard_threshold` fails validation (e.g. a zero cache
    /// size).
    /// </summary>
    public class LoaderConfig : FfiException
    {
        public LoaderConfig(string message)
            : base(message) { }
    }

    /// <summary>
    /// Kafka consumer configuration is invalid or incomplete.
    /// </summary>
    public class ConsumerConfiguration : FfiException
    {
        public ConsumerConfiguration(string message)
            : base(message) { }
    }

    /// <summary>
    /// Cassandra configuration is invalid or incomplete.
    /// </summary>
    public class CassandraConfiguration : FfiException
    {
        public CassandraConfiguration(string message)
            : base(message) { }
    }

    /// <summary>
    /// Topic configuration is invalid or incomplete.
    /// </summary>
    public class TopicConfiguration : FfiException
    {
        public TopicConfiguration(string message)
            : base(message) { }
    }

    /// <summary>
    /// A high-level client operation failed.
    ///
    /// Wraps errors from the main Prosody client API.
    /// </summary>
    public class Client : FfiException
    {
        public Client(string message)
            : base(message) { }
    }

    /// <summary>
    /// Construction of the backend-erased FFI client failed.
    /// </summary>
    public class ClientBuild : FfiException
    {
        public ClientBuild(string message)
            : base(message) { }
    }

    /// <summary>
    /// A producer operation failed.
    ///
    /// Occurs when publishing messages to Kafka fails.
    /// </summary>
    public class Producer : FfiException
    {
        public Producer(string message)
            : base(message) { }
    }

    /// <summary>
    /// An event context operation failed.
    ///
    /// Wraps errors from event acknowledgment and state management.
    /// </summary>
    public class EventContext : FfiException
    {
        public EventContext(string message)
            : base(message) { }
    }

    /// <summary>
    /// A timestamp value is invalid or out of range.
    /// </summary>
    public class CompactDateTime : FfiException
    {
        public CompactDateTime(string message)
            : base(message) { }
    }

    /// <summary>
    /// A background task failed or panicked.
    ///
    /// Indicates that an async task did not complete successfully.
    /// </summary>
    public class Join : FfiException
    {
        public Join(string message)
            : base(message) { }
    }

    /// <summary>
    /// A permanent keyed-state failure that must not be retried.
    ///
    /// Recovered structurally from the erased seam's
    /// [`ErasedCategory::Permanent`]: configuration or deployment mistakes
    /// (unregistered name, identity mismatch, duplicate name, invalid TTL). The
    /// `flat_error` attribute generates a distinct `FfiException` subclass, so
    /// the C# layer recovers the category from the exception type, never by
    /// parsing the message.
    /// </summary>
    public class PermanentState : FfiException
    {
        public PermanentState(string message)
            : base(message) { }
    }

    /// <summary>
    /// A transient keyed-state failure that may succeed on retry.
    ///
    /// Recovered structurally from the erased seam's
    /// [`ErasedCategory::Transient`], and the classification every caller/input
    /// mistake the glue detects folds into (null or unrepresentable writes,
    /// invalid values or indices) so a data-dependent handler bug
    /// retries rather than silently committing the offset and losing the
    /// message.
    /// </summary>
    public class TransientState : FfiException
    {
        public TransientState(string message)
            : base(message) { }
    }
}

class FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException>, CallStatusErrorHandler<FfiException>
{
    public static FfiConverterTypeFfiError INSTANCE = new FfiConverterTypeFfiError();

    public override FfiException Read(BigEndianStream stream)
    {
        var value = stream.ReadInt();
        switch (value)
        {
            case 1:
                return new FfiException.Cancelled(FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new FfiException.TopicContainsNul(FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new FfiException.UnexpectedCallback(FfiConverterString.INSTANCE.Read(stream));
            case 4:
                return new FfiException.Admin(FfiConverterString.INSTANCE.Read(stream));
            case 5:
                return new FfiException.Validation(FfiConverterString.INSTANCE.Read(stream));
            case 6:
                return new FfiException.TelemetryConfig(FfiConverterString.INSTANCE.Read(stream));
            case 7:
                return new FfiException.Tracing(FfiConverterString.INSTANCE.Read(stream));
            case 8:
                return new FfiException.LoaderConfig(FfiConverterString.INSTANCE.Read(stream));
            case 9:
                return new FfiException.ConsumerConfiguration(FfiConverterString.INSTANCE.Read(stream));
            case 10:
                return new FfiException.CassandraConfiguration(FfiConverterString.INSTANCE.Read(stream));
            case 11:
                return new FfiException.TopicConfiguration(FfiConverterString.INSTANCE.Read(stream));
            case 12:
                return new FfiException.Client(FfiConverterString.INSTANCE.Read(stream));
            case 13:
                return new FfiException.ClientBuild(FfiConverterString.INSTANCE.Read(stream));
            case 14:
                return new FfiException.Producer(FfiConverterString.INSTANCE.Read(stream));
            case 15:
                return new FfiException.EventContext(FfiConverterString.INSTANCE.Read(stream));
            case 16:
                return new FfiException.CompactDateTime(FfiConverterString.INSTANCE.Read(stream));
            case 17:
                return new FfiException.Join(FfiConverterString.INSTANCE.Read(stream));
            case 18:
                return new FfiException.PermanentState(FfiConverterString.INSTANCE.Read(stream));
            case 19:
                return new FfiException.TransientState(FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(
                    String.Format("invalid error value '{0}' in FfiConverterTypeFfiError.Read()", value)
                );
        }
    }

    public override int AllocationSize(FfiException value)
    {
        return 4 + FfiConverterString.INSTANCE.AllocationSize(value.Message);
    }

    public override void Write(FfiException value, BigEndianStream stream)
    {
        switch (value)
        {
            case FfiException.Cancelled:
                stream.WriteInt(1);
                break;
            case FfiException.TopicContainsNul:
                stream.WriteInt(2);
                break;
            case FfiException.UnexpectedCallback:
                stream.WriteInt(3);
                break;
            case FfiException.Admin:
                stream.WriteInt(4);
                break;
            case FfiException.Validation:
                stream.WriteInt(5);
                break;
            case FfiException.TelemetryConfig:
                stream.WriteInt(6);
                break;
            case FfiException.Tracing:
                stream.WriteInt(7);
                break;
            case FfiException.LoaderConfig:
                stream.WriteInt(8);
                break;
            case FfiException.ConsumerConfiguration:
                stream.WriteInt(9);
                break;
            case FfiException.CassandraConfiguration:
                stream.WriteInt(10);
                break;
            case FfiException.TopicConfiguration:
                stream.WriteInt(11);
                break;
            case FfiException.Client:
                stream.WriteInt(12);
                break;
            case FfiException.ClientBuild:
                stream.WriteInt(13);
                break;
            case FfiException.Producer:
                stream.WriteInt(14);
                break;
            case FfiException.EventContext:
                stream.WriteInt(15);
                break;
            case FfiException.CompactDateTime:
                stream.WriteInt(16);
                break;
            case FfiException.Join:
                stream.WriteInt(17);
                break;
            case FfiException.PermanentState:
                stream.WriteInt(18);
                break;
            case FfiException.TransientState:
                stream.WriteInt(19);
                break;
            default:
                throw new InternalException(
                    String.Format("invalid error value '{0}' in FfiConverterTypeFfiError.Write()", value)
                );
        }
    }
}

/// <summary>
/// Result code indicating how the event handler completed.
///
/// Handlers return this code to signal success or classify failures. Prosody
/// uses this classification to determine retry behavior and dead-letter queue
/// routing.
/// </summary>
internal enum HandlerResultCode : int
{
    /// <summary>
    /// Handler completed successfully.
    ///
    /// The message or timer was processed without error. Prosody will
    /// acknowledge the message and proceed to the next event.
    /// </summary>
    Success,

    /// <summary>
    /// Transient error that may resolve on retry.
    ///
    /// Use this for temporary failures like network timeouts, service
    /// unavailability, or rate limiting. Prosody will retry the event
    /// with exponential backoff.
    /// </summary>
    TransientError,

    /// <summary>
    /// Permanent error that will not resolve on retry.
    ///
    /// Use this for unrecoverable failures like malformed data, validation
    /// errors, or business logic violations. Prosody will route the event
    /// to the dead-letter queue without retrying.
    /// </summary>
    PermanentError,
}

class FfiConverterTypeHandlerResultCode : FfiConverterRustBuffer<HandlerResultCode>
{
    public static FfiConverterTypeHandlerResultCode INSTANCE = new FfiConverterTypeHandlerResultCode();

    public override HandlerResultCode Read(BigEndianStream stream)
    {
        var value = stream.ReadInt();
        switch (value)
        {
            case 1:
                return HandlerResultCode.Success;
            case 2:
                return HandlerResultCode.TransientError;
            case 3:
                return HandlerResultCode.PermanentError;
            default:
                throw new InternalException(
                    String.Format("invalid enum value '{0}' in FfiConverterTypeHandlerResultCode.Read()", value)
                );
        }
    }

    public override int AllocationSize(HandlerResultCode value)
    {
        return 4;
    }

    public override void Write(HandlerResultCode value, BigEndianStream stream)
    {
        switch (value)
        {
            case HandlerResultCode.Success:
                stream.WriteInt(1);
                break;
            case HandlerResultCode.TransientError:
                stream.WriteInt(2);
                break;
            case HandlerResultCode.PermanentError:
                stream.WriteInt(3);
                break;
            default:
                throw new InternalException(
                    String.Format("invalid enum value '{0}' in FfiConverterTypeHandlerResultCode.Write()", value)
                );
        }
    }
}

/// <summary>
/// Log severity level for messages from Rust to C#.
///
/// These values map directly to C#'s `Microsoft.Extensions.Logging.LogLevel`
/// enum, preserving integer discriminants for efficient FFI conversion.
/// </summary>
internal enum LogLevel : int
{
    /// <summary>
    /// Most detailed logging; may contain sensitive data.
    /// </summary>
    Trace,

    /// <summary>
    /// Detailed information useful during development and debugging.
    /// </summary>
    Debug,

    /// <summary>
    /// General operational information about application flow.
    /// </summary>
    Information,

    /// <summary>
    /// Potential issues or unexpected behavior that does not prevent operation.
    /// </summary>
    Warning,

    /// <summary>
    /// Errors that prevent a specific operation from completing.
    /// </summary>
    Error,

    /// <summary>
    /// Unrecoverable errors that require immediate attention.
    /// </summary>
    Critical,
}

class FfiConverterTypeLogLevel : FfiConverterRustBuffer<LogLevel>
{
    public static FfiConverterTypeLogLevel INSTANCE = new FfiConverterTypeLogLevel();

    public override LogLevel Read(BigEndianStream stream)
    {
        var value = stream.ReadInt();
        switch (value)
        {
            case 1:
                return LogLevel.Trace;
            case 2:
                return LogLevel.Debug;
            case 3:
                return LogLevel.Information;
            case 4:
                return LogLevel.Warning;
            case 5:
                return LogLevel.Error;
            case 6:
                return LogLevel.Critical;
            default:
                throw new InternalException(
                    String.Format("invalid enum value '{0}' in FfiConverterTypeLogLevel.Read()", value)
                );
        }
    }

    public override int AllocationSize(LogLevel value)
    {
        return 4;
    }

    public override void Write(LogLevel value, BigEndianStream stream)
    {
        switch (value)
        {
            case LogLevel.Trace:
                stream.WriteInt(1);
                break;
            case LogLevel.Debug:
                stream.WriteInt(2);
                break;
            case LogLevel.Information:
                stream.WriteInt(3);
                break;
            case LogLevel.Warning:
                stream.WriteInt(4);
                break;
            case LogLevel.Error:
                stream.WriteInt(5);
                break;
            case LogLevel.Critical:
                stream.WriteInt(6);
                break;
            default:
                throw new InternalException(
                    String.Format("invalid enum value '{0}' in FfiConverterTypeLogLevel.Write()", value)
                );
        }
    }
}

